1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.util.Collection;
4	import java.util.Locale;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Identity rule for owners: every owner has one derived {@code identityKey} that
10	 * combines its normalized telephone, email and household. A new owner duplicates an
11	 * existing one only when their WHOLE identityKey is equal, so two members of the same
12	 * household with different telephones (different keys) are both allowed.
13	 */
14	final class Identities {
15	
16	    private Identities() {
17	    }
18	
19	    /** The derived identity key: normalizedTelephone + '|' + (email or empty) + '|' + householdId. */
20	    static String identityKey(Owner owner) {
21	        return normalize(owner.getTelephone()) + "|" + normalize(owner.getEmail())
22	            + "|" + normalize(owner.getHouseholdId());
23	    }
24	
25	    /** Whether {@code candidate}'s whole identityKey already belongs to an existing owner. */
26	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
27	        String key = identityKey(candidate);
28	        return existing.stream().anyMatch(other -> key.equals(identityKey(other)));
29	    }
30	
31	    private static String normalize(String value) {
32	        return value == null ? "" : value.strip().toLowerCase(Locale.ROOT);
33	    }
34	}
