1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Soft-match rule for owners: a candidate is a possible duplicate of an existing owner
9	 * when they share the same last name (case-insensitive) and postcode but have a
10	 * different telephone, so it is created rather than rejected as a hard duplicate.
11	 */
12	final class PossibleDuplicates {
13	
14	    private PossibleDuplicates() {
15	    }
16	
17	    /**
18	     * The id of an existing owner {@code candidate} softly matches, or {@code null} if none.
19	     * A candidate that declares itself a household member ({@code sharesHousehold} true) is
20	     * never a suspected duplicate.
21	     */
22	    static Integer matchId(Collection<Owner> existing, Owner candidate, Boolean sharesHousehold) {
23	        if (Boolean.TRUE.equals(sharesHousehold)) {
24	            return null;
25	        }
26	        return existing.stream()
27	            .filter(other -> softMatch(other, candidate))
28	            .map(Owner::getId)
29	            .findFirst()
30	            .orElse(null);
31	    }
32	
33	    private static boolean softMatch(Owner a, Owner b) {
34	        return b.getPostcode() != null && b.getPostcode().equals(a.getPostcode())
35	            && a.getLastName() != null && a.getLastName().equalsIgnoreCase(b.getLastName())
36	            && a.getTelephone() != null && !a.getTelephone().equals(b.getTelephone());
37	    }
38	}
