47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        String idempotencyKey = IdempotencyKeys.current();
103	        Owner replayed = IdempotencyKeys.seen(idempotencyKey);
104	        if (replayed != null) {
105	            return new ResponseEntity<>(ownerMapper.toOwnerDto(replayed), HttpStatus.OK);
106	        }
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        owner.setHouseholdId(Households.idFor(owner));
110	        Collection<Owner> owners = this.clinicService.findAllOwners().stream()
111	            .filter(o -> !o.getDeleted()).toList();
112	        owner.setRegistrationDate(BusinessDays.effective(owner));
113	        if (owners.stream()
114	            .filter(o -> owner.getRegistrationDate().equals(o.getRegistrationDate())).count() >= 100) {
115	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
116	        }
117	        if (Identities.isDuplicate(owners, owner)) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        if (CityCodes.countInCity(owners, owner) >= 50) {
121	            return new ResponseEntity<>(HttpStatus.CONFLICT);
122	        }
123	        owner.setHouseholdMemberCount(Households.size(owners, owner));
124	        owner.setMembershipLevelCap(Households.ceilingLevel(owners, owner));
125	        owner.assignCustomerCode(owners);
126	        owner.setNamesakeCount(Namesakes.count(owners, owner));
127	        owner.setBulkSignupWarning(BulkSignups.exceededDailyLimit(owners, owner));
128	        owner.setPossibleDuplicateOf(
129	            PossibleDuplicates.matchId(owners, owner, ownerFieldsDto.getSharesHousehold()));
130	        this.clinicService.saveOwner(owner);
131	        IdempotencyKeys.remember(idempotencyKey, owner);
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        headers.setLocation(UriComponentsBuilder.newInstance()
134	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
135	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
141	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
142	        if (currentOwner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        currentOwner.setAddress(ownerFieldsDto.getAddress());
146	        currentOwner.setCity(ownerFieldsDto.getCity());
147	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
148	        currentOwner.setLastName(ownerFieldsDto.getLastName());
149	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
150	        this.clinicService.saveOwner(currentOwner);
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Transactional
156	    @Override
157	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        owner.setDeleted(true);
163	        this.clinicService.saveOwner(owner);
164	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        HttpHeaders headers = new HttpHeaders();
175	        Pet pet = petMapper.toPet(petFieldsDto);
176	        owner.setId(ownerId);
177	        pet.setOwner(owner);
178	        pet.getType().setName(null);
179	        this.clinicService.savePet(pet);
180	        PetDto petDto = petMapper.toPetDto(pet);
181	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
182	            .buildAndExpand(pet.getId()).toUri());
183	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
189	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
190	        if (currentOwner != null) {
191	            Pet currentPet = this.clinicService.findPetById(petId);
192	            if (currentPet != null) {
193	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
194	                currentPet.setName(petFieldsDto.getName());
195	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
196	                this.clinicService.savePet(currentPet);
197	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
198	            }
199	        }
200	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
206	        HttpHeaders headers = new HttpHeaders();
207	        Visit visit = visitMapper.toVisit(visitFieldsDto);
208	        Pet pet = new Pet();
209	        pet.setId(petId);
210	        visit.setPet(pet);
211	        this.clinicService.saveVisit(visit);
212	        VisitDto visitDto = visitMapper.toVisitDto(visit);
213	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
214	            .buildAndExpand(visit.getId()).toUri());
215	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
216	    }
217	
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
222	        Owner owner = this.clinicService.findOwnerById(ownerId);
223	        if (owner != null) {
224	            Pet pet = owner.getPet(petId);
225	            if (pet != null) {
226	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
227	            }
228	        }
229	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	    }
231	}
