14	public class DisposableEmailValidator implements ConstraintValidator<DisposableEmailValidation, String> {
15	
16	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
17	        "mailinator.com", "tempmail.com", "guerrillamail.com");
